{"command":"cd /workspace && python3 - <<'PY'
import subprocess, json, os
root_out=subprocess.run(['./executable','--json-usage'], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True).stdout
root=json.loads(root_out)
paths=[[]]
def walk(n):
    fp=n.get('full_path')
    if fp: paths.append(fp[1:])
    for s in n.get('sub_algorithms',[]): walk(s)
walk(root)
# add aliases/shortcuts help paths
extra=[['info'],['convert']]
for p in extra:
    if p not in paths: paths.append(p)
helps={}
errs={}
for p in paths:
    cmd=['./executable']+p+['--help']
    r=subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    key=' '.join(p)
    helps[key]={'stdout':r.stdout,'stderr':r.stderr,'returncode':r.returncode}
    if r.returncode!=0: errs[key]=(r.returncode,r.stderr[:200])
print('paths',len(paths),'errs',errs)
os.makedirs('resources', exist_ok=True)
with open('resources/help_texts.json','w') as f: json.dump(helps,f,ensure_ascii=False)
with open('resources/usage_root.json','w') as f: f.write(root_out)
print('help bytes', os.path.getsize('resources/help_texts.json'), 'usage bytes', os.path.getsize('resources/usage_root.json'))
PY
ls -lh resources"}

